# ---- Rendering. ----
#
# New texts: an optional third argument names a JSON file that maps an entry's
# number, such as "P-37", to its new text, written as POSITIONS.md writes the
# line: "P-37 **Bold title.** Text ..." (a leading "- " is allowed). An entry
# with a new text gets a word diff against its current text, with the current
# text collapsed under it; an entry without one shows its current text and
# says that the rewrite has not run yet.

import difflib
import json

NEW = {}
if len(sys.argv) > 3:
    NEW = json.load(open(sys.argv[3], encoding="utf-8"))

# A short name for each entry's heading; the bold title stays in the text.
HANDLES = {
    37: "One library for both paths",
    26: "The team's later word",
    43: "The exclusion rule and the flat numbers",
    158: "Abstract members of an api",
    7: "The goal and its measure",
    27: "The library's own practice",
    146: "`self` in a self-typed trait",
    153: "The integer power",
    154: "The order of lists",
    12: "Walk runs the checker",
    17: "Unboxed doubles",
    33: "The phases of the work",
    42: "The default bound",
    58: "The natives' form",
    59: "Walk's choice of coercion",
    84: "The `double[]` store",
    85: "The open array questions",
    155: "Symbolic operators",
}

TOKEN = re.compile(r"(?:[^\s`]|`[^`]*`)+")


def split_line(num, line):
    """'- P-N **title** body' -> (title, body), both Markdown."""
    line = line[2:] if line.startswith("- ") else line
    m = re.match(r"P-%d \*\*(.+?)\*\* ?(.*)$" % num, line, re.S)
    if not m:
        raise SystemExit(f"P-{num}: the text does not start 'P-{num} **title**'")
    return m.group(1), m.group(2)


def plain(md):
    return md.replace("`", "")


def word_diff(old, new):
    """HTML of new against old: <ins> for added words; an empty
    <del data-old="..."> where words were removed, which CSS shows struck
    through and which a selection, so Speak, leaves out."""
    a, b = TOKEN.findall(old), TOKEN.findall(new)
    out = []
    for op, i1, i2, j1, j2 in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        if op == "equal":
            out.append(inline(" ".join(b[j1:j2])))
            continue
        if op in ("delete", "replace"):
            out.append('<del data-old="%s"></del>' % html.escape(plain(" ".join(a[i1:i2])), quote=True))
        if op in ("insert", "replace"):
            out.append("<ins>%s</ins>" % inline(" ".join(b[j1:j2])))
    return " ".join(out)


def text_html(num, title, body):
    return f"P-{num} <strong>{title}</strong> {body}"


