.reasons h4.label { margin-top: 0; }
ol.findings { margin-bottom: .2rem; }
ol.findings > li { margin-bottom: .7rem; }
ol.findings > li > p { margin: 0 0 .25rem; }
ol.findings ul { margin: .2rem 0 .3rem; }
.at-issue { color: var(--muted); }
.at-issue .quote { color: var(--fg); font-style: italic; }
.part-intro { color: var(--muted); }
</style>"""

parts_html = []
nav_items = []
for part in PARTS:
    refs = []
    body = [render_entry(n, f, refs) for n, f in part["entries"]]
    chunk_path = CORR + part["chunk"] + "/findings.md"
    refs.insert(0, f'<li>The run\'s input for this part, its findings cut word for word from the findings list: {link(chunk_path, "<code>corrections/" + part["chunk"] + "/findings.md</code>")}.</li>')
    sec = [f'<section id="{part["id"]}" class="part">',
           f'<h2><span class="num">{part["num"]}</span>{part["title"]}</h2>',
           f'<p class="part-intro">{part["intro"]}</p>']
    sec += body
    sec.append('<div class="sources"><span class="label">References</span>\n<ul>\n' + "\n".join(refs) + "\n</ul>\n</div>")
    sec.append("</section>")
    parts_html.append("\n".join(sec))
    nums = ", ".join(f'<a href="#p-{n}">P-{n}</a>' for n, _ in part["entries"])
    nav_items.append(f'<li><a href="#{part["id"]}">{part["num"]}, {part["title"].split(":")[0].lower()}</a><p class="nums">{nums}</p></li>')

unknown = set(NEW) - {f"P-{n}" for p in PARTS for n, _ in p["entries"]}
if unknown:
    raise SystemExit("new texts for entries not on the page: " + ", ".join(sorted(unknown)))

head = f"""<title>Foundations Corrections Baseline</title>
<meta name="description" content="The 18 POSITIONS entries in which the foundations review found faults: each entry's new text as a change against its current text once its part has run, the current text until then, and the findings on it, in three parts.">
{fonts}
{css}
{page_css}
"""

masthead = """<header class="masthead">
<p class="eyebrow">Fortress revival &middot; foundations corrections &middot; 28 October 2026</p>
