.at-issue { color: var(--muted); }
.at-issue .quote { color: var(--fg); font-style: italic; }
.part-intro { color: var(--muted); }
</style>"""

parts_html = []
nav_items = []
for part in PARTS:
    refs = []
    body = [render_entry(n, f, refs) for n, f in part["entries"]]
    chunk_path = CORR + part["chunk"] + "/findings.md"
    refs.insert(0, f'<li>The run\'s input for this part, its findings cut word for word from the findings list: {link(chunk_path, "<code>corrections/" + part["chunk"] + "/findings.md</code>")}.</li>')
    sec = [f'<section id="{part["id"]}" class="part">',
           f'<h2><span class="num">{part["num"]}</span>{part["title"]}</h2>',
           f'<p class="part-intro">{part["intro"]}</p>']
    sec += body
    sec.append('<div class="sources"><span class="label">References</span>\n<ul>\n' + "\n".join(refs) + "\n</ul>\n</div>")
    sec.append("</section>")
    parts_html.append("\n".join(sec))
    nums = ", ".join(f'<a href="#p-{n}">P-{n}</a>' for n, _ in part["entries"])
    nav_items.append(f'<li><a href="#{part["id"]}">{part["num"]}, {part["title"].split(":")[0].lower()}</a><p class="nums">{nums}</p></li>')

unknown = set(NEW) - {f"P-{n}" for p in PARTS for n, _ in p["entries"]}
if unknown:
    raise SystemExit("new texts for entries not on the page: " + ", ".join(sorted(unknown)))

head = f"""<title>Foundations Corrections Baseline</title>
<meta name="description" content="The 18 POSITIONS entries in which the foundations review found faults: each entry's new text as a change against its current text once its part has run, the current text until then, and the findings on it, in three parts.">
{fonts}
{css}
{page_css}
"""

masthead = """<header class="masthead">
<p class="eyebrow">Fortress revival &middot; foundations corrections &middot; 28 October 2026</p>
<h1>The eighteen entries, before their corrections</h1>
<p class="standfirst">This page is now the baseline for the corrections that are about to run. It holds the 18 entries in which the foundations review found faults. The thirteen rewritten texts of 26 October, which you rejected, are removed from this page.</p>
<p class="standfirst">Each entry has its own section and its own Select button. Its main block holds the new text. Until its part has run, the block shows the current text. When the new text comes, the block marks the change: added words are underlined, and removed words are struck through. The current text is then collapsed under it. The findings on the current text sit below the block. The entry's Select button leaves them out. Each part's own Select button selects the whole part, findings included.</p>
<p class="standfirst">The corrections run in three parts: a pilot of four entries, then two chunks of seven, each after your read of the part before. Some findings cite the test of 26 October, in which an agent that read the current entries answered cases built to mislead. References sit at the end of each part.</p>
</header>"""

nav = '<nav class="parts" aria-label="Parts">\n<h2>Three parts</h2>\n<ol>\n' + "\n".join(nav_items) + "\n</ol>\n</nav>"

footer = f"""<footer class="colophon">
<p>From <code>POSITIONS.md</code> and the findings list, <code>salvage-findings.md</code>, at commit <code>{COMMIT[:9]}</code>. "The judgement" is the foundations review's judgement.</p>
</footer>"""

doc = head + '\n<div class="page">\n' + masthead + "\n\n" + nav + "\n\n" + "\n\n".join(parts_html) + "\n\n" + footer + "\n</div>\n\n" + script + "\n"
open(OUT, "w", encoding="utf-8").write(doc)
print("wrote", OUT, len(doc.encode("utf-8")), "bytes;", len(NEW), "new texts")

